solution:
def parse_line(line):
    date, time, level, msg = line.split(" ", 3)
    return {"time": date + " " + time, "level": level, "msg": msg}

def parse_all(text):
    return [parse_line(l) for l in text.splitlines() if l.strip()]

def count_levels(entries):
    counts = {}
    for e in entries:
        counts[e["level"]] = counts.get(e["level"], 0) + 1
    return counts
